import { SearchBox, Card } from "march/ui"

// emoji bulucu: her tuşta hemen süzer (debounce 0); bulunanlar koyu kartta büyük büyük dizilir
const EMOJIS = [
  { char: "❤️", name: "kalp" }, { char: "🔥", name: "ateş" }, { char: "🎉", name: "kutlama" }, { char: "☕", name: "kahve" },
  { char: "🌙", name: "ay gece" }, { char: "☀️", name: "güneş" }, { char: "🚀", name: "roket" }, { char: "🍕", name: "pizza" },
  { char: "🐱", name: "kedi" }, { char: "🎧", name: "müzik kulaklık" }, { char: "⚡", name: "şimşek" }, { char: "🌊", name: "deniz dalga" },
]

export function EmojiFinder() {
  let $q = ""
  const $found = EMOJIS.filter((e) => e.name.includes($q.toLocaleLowerCase("tr")))
  return <Card m:theme="night">
    <SearchBox bind:value={$q} debounce={0} size="sm" placeholder="kalp, roket, kahve…" label="Emoji ara" />
    <div sx={{ flex: ["row", "wrap"], gap: 2, text: "2xl", p: 2 }}>
      {$found.length ? $found.map((e) => <span title={e.name}>{e.char}</span>) : <span sx={{ text: "sm", color: "muted" }}>Böyle bir emoji yok 🤷</span>}
    </div>
  </Card>
}

import { SearchBox, Card, Badge } from "march/ui"

// ekip yönetimi: üye listesinde arama; "/" tuşu kutuya odaklar, yazı 250 ms durunca süzülür,
// ad, e-posta ya da rol eşleşir; sonuç yoksa ne arandığı söylenir
interface Member { name: string; mail: string; role: "Yönetici" | "Editör" | "Okur" }

const MEMBERS: Member[] = [
  { name: "Ayşe Kaya", mail: "ayse@hadisosyal.com", role: "Yönetici" },
  { name: "Mehmet Demir", mail: "mehmet@hadisosyal.com", role: "Editör" },
  { name: "Zeynep Arslan", mail: "zeynep@hadisosyal.com", role: "Editör" },
  { name: "Can Öztürk", mail: "can@hadisosyal.com", role: "Okur" },
  { name: "Elif Şahin", mail: "elif@hadisosyal.com", role: "Okur" },
]
const TONES = { "Yönetici": "danger", "Editör": "info", "Okur": "neutral" } as const

export function MemberSearch() {
  let $q = ""
  const $needle = $q.trim().toLocaleLowerCase("tr")
  const $rows = MEMBERS.filter((m) => `${m.name} ${m.mail} ${m.role}`.toLocaleLowerCase("tr").includes($needle))
  return <Card title="Ekip üyeleri" subtitle={`${$rows.length} / ${MEMBERS.length} üye`}>
    <SearchBox bind:value={$q} shortcut placeholder="Ad, e-posta ya da rol…" label="Üye ara" />
    <ul sx={{ flex: "col", gap: 2, p: 0 }}>
      {$rows.length ? $rows.map((m) => <li sx={{ flex: ["row", "between"], gap: 2 }}>
        <span>{m.name} <span sx={{ text: "sm", color: "muted" }}>{m.mail}</span></span>
        <Badge tone={TONES[m.role]}>{m.role}</Badge>
      </li>) : <li sx={{ color: "muted" }}>"{$q}" ile eşleşen üye yok</li>}
    </ul>
  </Card>
}

import { SearchBox, Card } from "march/ui"
import { Icon, filter, trash } from "march/icons"

// SearchBox'ın bütün özellikleri bir arada: bağlı değer (bind:value), gecikme (debounce), onInput / onSearch / onEnter,
// kısayol ve ipucu (shortcut, shortcutHint), boyut, kenarsız görünüm, ikon ve temizle düğmesi (kapalı ya da kendi
// ikonun, clearLabel), erişilebilir ad (label), combobox kipi (controls, activeDescendant, expanded, onKeyDown),
// devre dışı, id, sınıf, inputClass ve inputRef
const FRUITS = ["elma", "armut", "erik", "incir", "kiraz", "karpuz"]

const Section = (props: { title: string; children?: unknown }) => <div sx={{ flex: "col", gap: 1 }}>
  <span sx={{ text: "xs", color: "muted" }}>{props.title}</span>
  {props.children}
</div>

export function SearchBoxLab() {
  let $q = ""
  let $typed = ""
  let $searched = ""
  let $entered = ""
  let $fruitQ = ""
  let $active = -1
  let $picked = ""
  let $filterQ = ""
  let $refTag = ""
  const $fruits = FRUITS.filter((f) => f.includes($fruitQ))
  const keys = (e: KeyboardEvent) => {
    if (e.key === "ArrowDown") { e.preventDefault(); $active = Math.min($active + 1, $fruits.length - 1) }
    else if (e.key === "ArrowUp") { e.preventDefault(); $active = Math.max($active - 1, 0) }
    else if (e.key === "Enter" && $active >= 0) { e.preventDefault(); $picked = $fruits[$active] ?? "" }
  }
  return <div sx={{ flex: "col", gap: 4 }}>
    <Section title="Gecikmeli değer (debounce 800), onInput, onSearch, onEnter, kısayol Ctrl K">
      <SearchBox bind:value={$q} debounce={800} onInput={(x: string) => $typed = x} onSearch={(x: string) => $searched = x}
        onEnter={(x: string) => $entered = x} shortcut="mod+k" label="Ürün ara" placeholder="Ürün, marka…"
        id="lab-search" class="lab-search" inputClass="lab-search-input" inputRef={(el: HTMLInputElement) => $refTag = el.tagName} />
      <span>Yazılan: {$typed} · aranan: {$searched} · Enter: {$entered} · ref: {$refTag}</span>
    </Section>
    <Section title="Combobox: ok tuşları listede gezer, Enter seçer">
      <SearchBox bind:value={$fruitQ} debounce={0} onInput={() => $active = -1} label="Meyve seç"
        controls="lab-fruits" activeDescendant={$active >= 0 ? `lab-fruit-${$active}` : ""} expanded={$fruits.length > 0} onKeyDown={keys} />
      <ul id="lab-fruits" role="listbox" aria-label="Meyveler" sx={{ flex: ["row", "wrap"], gap: 2 }}>
        {$fruits.map((f, i) => <li id={`lab-fruit-${i}`} role="option" aria-selected={i === $active ? "true" : "false"}
          sx={{ text: i === $active ? "bold" : "sm", color: i === $active ? "primary" : "muted" }}>{f}</li>)}
      </ul>
      <span>Seçilen: {$picked || "—"}</span>
    </Section>
    <Section title="Kendi ikonu ve temizle ikonu, küçük boy">
      <SearchBox bind:value={$filterQ} debounce={0} size="sm" icon={<Icon of={filter} />} clear={<Icon of={trash} />}
        clearLabel="Süzgeci temizle" placeholder="Süz…" label="Sipariş süz" shortcut="/" shortcutHint={false} />
      <span>Süzgeç: {$filterQ || "boş"}</span>
    </Section>
    <Card m:theme="night">
      <Section title="Kenarsız, ikonsuz, temizlesiz; devre dışı">
        <SearchBox variant="plain" icon={false} clear={false} placeholder="Komut yaz…" label="Komut" />
        <SearchBox disabled placeholder="Arama kapalı" label="Kapalı arama" />
      </Section>
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { SearchBoxLab } from "./SearchBoxLab.tsx"

// SearchBoxLab'in testleri: kaydedince Testler sekmesinde çalışır
const key = async (el: Element, k: string) => {
  el.dispatchEvent(new KeyboardEvent("keydown", { key: k, bubbles: true, cancelable: true }))
  await new Promise((r) => setTimeout(r, 0))
}

test("onInput her tuşta, onSearch gecikmeden sonra, onEnter hemen", async () => {
  const s = renderTest(() => <SearchBoxLab />)
  const box = await s.type("Ürün ara", "kalem")
  expect(s.text().includes("Yazılan: kalem")).toBe(true)
  await s.wait(() => s.text().includes("aranan: kalem"), { timeout: 3000 })
  await key(box, "Enter")
  expect(s.text().includes("Enter: kalem")).toBe(true)
  expect(s.text().includes("ref: INPUT")).toBe(true)
  expect(box.classList.contains("lab-search-input")).toBe(true)
})

test("combobox: aria bağları, ok tuşu vurgular, Enter seçer", async () => {
  const s = renderTest(() => <SearchBoxLab />)
  const box = s.find("Meyve seç")!
  expect(box.getAttribute("role")).toBe("combobox")
  expect(box.getAttribute("aria-controls")).toBe("lab-fruits")
  expect(box.getAttribute("aria-expanded")).toBe("true")
  await key(box, "ArrowDown")
  await key(box, "ArrowDown")
  expect(box.getAttribute("aria-activedescendant")).toBe("lab-fruit-1")
  await key(box, "Enter")
  expect(s.text().includes("Seçilen: armut")).toBe(true)
})

test("yazınca kendi temizle düğmesi çıkar, basınca kutu boşalır", async () => {
  const s = renderTest(() => <SearchBoxLab />)
  expect(s.find("Süzgeci temizle")).toBe(null)
  await s.type("Sipariş süz", "kargoda")
  expect(s.text().includes("Süzgeç: kargoda")).toBe(true)
  await s.click("Süzgeci temizle")
  expect(s.text().includes("Süzgeç: boş")).toBe(true)
})

test("Escape temizler; devre dışı kutu kilitli", async () => {
  const s = renderTest(() => <SearchBoxLab />)
  const box = await s.type("Sipariş süz", "iade")
  await key(box, "Escape")
  expect(s.text().includes("Süzgeç: boş")).toBe(true)
  expect(s.find("Kapalı arama")?.hasAttribute("disabled")).toBe(true)
  expect(s.get(".lab-search")?.getAttribute("role")).toBe("search")
})
